with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published)
select id,'الديناميكا الجوية المتقدمة والتحليل السينوبتيكي','الدوران المحتمل والموجات والتيار النفاث والجبهات والأنظمة الجوية الإقليمية والتشخيص المتكامل.',51,false from c
on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الديناميكا الجبهية والموجية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأنظمة الجوية الإقليمية والتشخيص',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('potential-vorticity-dynamics','الدوران المحتمل وديناميكية الغلاف الجوي','ربط الدوران والاستقرار والبنية الحرارية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"الدوران المحتمل كمية ديناميكية تجمع معلومات الدوران والطبقية، وتفيد في تتبع تطور الأنظمة الجوية على المقاييس السينوبتيكية. تتطلب قراءته تحديد الإحداثيات والسطح المستخدم والافتراضات الديناميكية، ولا ينبغي تفسير خرائطه بمعزل عن الحرارة والرياح."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل الدوران المحتمل وديناميكية الغلاف الجوي الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم الدوران المحتمل وديناميكية الغلاف الجوي على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل خريطة دوران محتمل على سطح ضغط وحدد مناطق الشذوذ وما يلزم لفهم تطورها."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الدوران المحتمل وديناميكية الغلاف الجوي أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6360,55,'["شرح آليات الدوران المحتمل وديناميكية الغلاف الجوي","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('rossby-wave-breaking','انكسار موجات روسبي','التواء الموجات وتبادل الكتل الهوائية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد يؤدي تضخم موجات روسبي وانكسارها إلى تشوهات كبيرة في التيار النفاث وتبادل الهواء بين العروض. تختلف أنماط الانكسار وآثارها بحسب بنية الدوامية والتدفق الخلفي وتطور الموجة."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل انكسار موجات روسبي الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم انكسار موجات روسبي على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن نمط انكسار موجة روسبي مع نمط موجة غير منكسرة باستخدام خرائط ارتفاع 500 هكتوباسكال."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر انكسار موجات روسبي أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6370,55,'["شرح آليات انكسار موجات روسبي","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('jet-streak-four-quadrants','مناطق التسارع والتباطؤ في التيار النفاث','التباعد العلوي والاستجابة الرأسية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ عن تغير سرعة الرياح على طول التيار النفاث أنماط من التباعد والتقارب العلويين، لكن الاستجابة الفعلية تعتمد على انحناء التيار والحرارة والدوامية. لا تكفي قاعدة الأرباع وحدها لتحديد موقع الصعود في جميع الحالات."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل مناطق التسارع والتباطؤ في التيار النفاث الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم مناطق التسارع والتباطؤ في التيار النفاث على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد مناطق محتملة للتباعد العلوي حول منطقة سرعة قصوى، ثم تحقق من الحركة الرأسية وحقول الدوامية."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر مناطق التسارع والتباطؤ في التيار النفاث أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6380,55,'["شرح آليات مناطق التسارع والتباطؤ في التيار النفاث","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('baroclinic-instability','عدم الاستقرار الباروكليـني','تحويل طاقة التدرج الحراري إلى اضطرابات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ عدم الاستقرار الباروكليـني عندما تسمح البنية الحرارية والقص الرأسي بنمو اضطرابات تستمد طاقتها من التدرج الحراري الأفقي. يفسر جانباً أساسياً من تطور المنخفضات خارج المدارية."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل عدم الاستقرار الباروكليـني الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم عدم الاستقرار الباروكليـني على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف ترتبط الجبهة الحرارية والقص الرأسي بنمو اضطراب باروكليـني."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر عدم الاستقرار الباروكليـني أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6390,55,'["شرح آليات عدم الاستقرار الباروكليـني","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('barotropic-instability','عدم الاستقرار الباروتروبي','قص الرياح الأفقية ونمو الدوامات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يرتبط عدم الاستقرار الباروتروبي بقص أفقي في التدفق يمكن أن يسمح بنمو اضطرابات تستمد طاقتها من التدرج في الزخم. يختلف عن عدم الاستقرار الباروكليـني الذي يرتبط أساساً بالبنية الحرارية الرأسية."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل عدم الاستقرار الباروتروبي الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم عدم الاستقرار الباروتروبي على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مصادر الطاقة في عدم الاستقرار الباروتروبي والباروكليـني."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر عدم الاستقرار الباروتروبي أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6400,55,'["شرح آليات عدم الاستقرار الباروتروبي","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('frontogenesis-frontolysis','تكوّن الجبهات واضمحلالها','تغير التدرج الحراري الأفقي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يشير تكوّن الجبهات إلى ازدياد التدرج الحراري الأفقي بفعل التشوه والتقارب والتدفقات، بينما يعني اضمحلالها ضعف ذلك التدرج. قد يرتبط التكوّن بحركة رأسية ثانوية وهطول منظم."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل تكوّن الجبهات واضمحلالها الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم تكوّن الجبهات واضمحلالها على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"استخدم خريطة حرارة ورياح لتحديد منطقة تكوّن جبهة محتملة، واذكر حدود الاستنتاج."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر تكوّن الجبهات واضمحلالها أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6410,55,'["شرح آليات تكوّن الجبهات واضمحلالها","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('quasigeostrophic-theory','نظرية شبه الجيوستروفية','تقريب الحركة الرأسية في العروض الوسطى','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم النظرية شبه الجيوستروفية فصل الحركة إلى مركبة جيوستروفية ومركبة ثانوية أضعف، وتربط الحركة الرأسية بتأثيرات الدوامية والحرارة. تصلح إطاراً تفسيرياً في ظروف معينة وليست وصفاً كاملاً لكل الحالات."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل نظرية شبه الجيوستروفية الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم نظرية شبه الجيوستروفية على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر إشارة الحركة الرأسية المتوقعة من مساهمتي الدوامية والحرارة في حالة مبسطة."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر نظرية شبه الجيوستروفية أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6420,55,'["شرح آليات نظرية شبه الجيوستروفية","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('omega-equation-diagnostics','معادلة أوميغا التشخيصية','تقدير الحركة الرأسية من forcing الديناميكي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تربط معادلة أوميغا الحركة الرأسية بالتأثيرات الديناميكية والحرارية في الغلاف الجوي. تعتمد النتيجة على الإحداثيات والافتراضات وشروط الحدود، وتستخدم لتفسير بيئة الصعود والهبوط لا لإنتاج قياس مباشر."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل معادلة أوميغا التشخيصية الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم معادلة أوميغا التشخيصية على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقرأ حقل أوميغا على مستويات متعددة واربطه بتوزيع السحب والهطول المرصود."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر معادلة أوميغا التشخيصية أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6430,55,'["شرح آليات معادلة أوميغا التشخيصية","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('thermal-wind-relationship','علاقة الرياح الحرارية','القص الرأسي والتدرج الحراري الأفقي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تربط الرياح الحرارية القص الرأسي للرياح الجيوستروفية بالتدرج الأفقي في درجة الحرارة. تساعد العلاقة على فحص الاتساق بين خرائط الحرارة والرياح، مع الانتباه إلى اصطلاح الإحداثيات والإشارات."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل علاقة الرياح الحرارية الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم علاقة الرياح الحرارية على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"استنتج نوع القص الرأسي المتوقع من تدرج حراري أفقي معروف في نصف الكرة الشمالي."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر علاقة الرياح الحرارية أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6440,55,'["شرح آليات علاقة الرياح الحرارية","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('geostrophic-adjustment','التوازن الجيوستروفي والتكيف','استجابة الضغط والرياح للاضطرابات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل التكيف الجيوستروفي تطوراً نحو توازن تقريبي بين تدرج الضغط وقوة كوريوليس بعد اضطراب أولي. قد تنتج عنه موجات داخلية وتغيرات في توزيع الكتلة والرياح."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل التوازن الجيوستروفي والتكيف الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم التوازن الجيوستروفي والتكيف على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح بصورة نوعية كيف تستجيب الرياح والضغط لاضطراب أولي في مجال الضغط."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر التوازن الجيوستروفي والتكيف أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6450,55,'["شرح آليات التوازن الجيوستروفي والتكيف","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الديناميكا الجبهية والموجية'),
('inertial-gravity-waves','موجات الثقالة الداخلية','التذبذب بين الطفو وقوة كوريوليس','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنتشر موجات الثقالة الداخلية في وسط مستقر بفعل قوة الطفو، وتتأثر بتأثير كوريوليس والقص والتدرج الرأسي. تنقل الطاقة والزخم وقد تظهر في السحب الموجية واضطرابات الطبقات العليا."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل موجات الثقالة الداخلية الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم موجات الثقالة الداخلية على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد مؤشرات رصدية قد تدل على موجات ثقالة داخلية، وميزها عن السحب الحملية."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر موجات الثقالة الداخلية أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6460,55,'["شرح آليات موجات الثقالة الداخلية","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('atmospheric-tides','المد والجزر الجوي','الدورات الحرارية والجاذبية في الضغط والرياح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتضمن المدود الجوية تذبذبات دورية في الضغط والرياح، منها مكونات حرارية مرتبطة بالتسخين الشمسي وأخرى جاذبية. يتطلب فصلها تحليل السلاسل الزمنية ومراعاة التغيرات الجوية العابرة."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل المد والجزر الجوي الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم المد والجزر الجوي على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح طريقة تحليل زمنية لفصل المكون اليومي عن تغيرات الطقس غير الدورية."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر المد والجزر الجوي أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6470,55,'["شرح آليات المد والجزر الجوي","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('stratosphere-troposphere-coupling','الاقتران بين الستراتوسفير والتروبوسفير','انتقال الإشارات الديناميكية بين الطبقات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمكن للتغيرات الستراتوسفيرية أن ترتبط بتغيرات لاحقة في دوران التروبوسفير، لكن الاقتران ليس حتمياً ولا يحدث بالمدة نفسها في كل حالة. يتطلب التشخيص تتبع الدوامية والحرارة والرياح عبر طبقات متعددة."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل الاقتران بين الستراتوسفير والتروبوسفير الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم الاقتران بين الستراتوسفير والتروبوسفير على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مخططاً زمنياً لمتابعة حدث ستراتوسفيري والتحقق من أثره المحتمل في التروبوسفير."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الاقتران بين الستراتوسفير والتروبوسفير أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6480,55,'["شرح آليات الاقتران بين الستراتوسفير والتروبوسفير","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('sudden-stratospheric-warming-diagnostics','تشخيص الاحترار الستراتوسفيري المفاجئ','انعكاس الرياح الغربية وارتفاع الحرارة القطبية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتميز الاحترار الستراتوسفيري المفاجئ بارتفاع ملحوظ في حرارة الستراتوسفير القطبية وتغيرات كبيرة في الدوامية والرياح الغربية. يختلف الأثر اللاحق على الطقس السطحي من حالة إلى أخرى."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل تشخيص الاحترار الستراتوسفيري المفاجئ الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم تشخيص الاحترار الستراتوسفيري المفاجئ على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد الحقول والمستويات التي ينبغي فحصها لتشخيص حدث احترار ستراتوسفيري."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر تشخيص الاحترار الستراتوسفيري المفاجئ أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6490,55,'["شرح آليات تشخيص الاحترار الستراتوسفيري المفاجئ","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('blocking-high-dynamics','ديناميكية المرتفعات الحاجزة','استمرار الأنماط الجوية وانحراف المسارات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"المرتفع الحاجز نمط دوران واسع ومستمر نسبياً يعيق الحركة المعتادة للأنظمة الجوية. قد يرتبط بفترات طويلة من الحرارة أو البرودة أو الجفاف أو الهطول، لكن الأثر المحلي يتوقف على الموقع والموسم."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل ديناميكية المرتفعات الحاجزة الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم ديناميكية المرتفعات الحاجزة على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل خريطة ارتفاعات متعددة الأيام لتحديد احتمال وجود نمط حجب جوي."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر ديناميكية المرتفعات الحاجزة أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6500,55,'["شرح آليات ديناميكية المرتفعات الحاجزة","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('cutoff-low-formation','تكوّن المنخفضات المقطوعة','انفصال الدوامة الباردة عن التيار الغربي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد ينفصل جيب من الهواء البارد والدوامية عن التيار النفاث ويتحول إلى منخفض علوي مقطوع. تتباين حركته وبقاؤه وتأثيره بحسب التدفق المحيط والرطوبة والتضاريس."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل تكوّن المنخفضات المقطوعة الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم تكوّن المنخفضات المقطوعة على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد العلامات التي تميز منخفضاً علوياً مقطوعاً عن أخدود متصل بالتيار النفاث."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر تكوّن المنخفضات المقطوعة أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6510,55,'["شرح آليات تكوّن المنخفضات المقطوعة","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('mediterranean-cyclogenesis','نشوء المنخفضات في حوض المتوسط','التفاعل بين البحر والهواء البارد والتضاريس','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتأثر نشوء المنخفضات المتوسطية بتباين حرارة البحر والهواء العلوي والقص والتضاريس وتفاعلات الجبهات. تختلف الحالات من منخفضات جبهية واسعة إلى أنظمة شبه استوائية محدودة الخصائص."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل نشوء المنخفضات في حوض المتوسط الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم نشوء المنخفضات في حوض المتوسط على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن حالة نشوء منخفض فوق المتوسط مع منخفض عابر من الغرب باستخدام خرائط الضغط والحرارة."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر نشوء المنخفضات في حوض المتوسط أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6520,55,'["شرح آليات نشوء المنخفضات في حوض المتوسط","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('subtropical-cyclone-structure','بنية المنخفضات شبه الاستوائية','الخصائص الهجينة والانتقال بين الأنظمة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تجمع بعض المنخفضات شبه الاستوائية خصائص مدارية وباروكليـنية، مع بنية حرارية ورياح تختلف عن الأعاصير المدارية الكاملة. يتطلب تصنيفها استخدام بنية الحرارة والرياح والسحب ومصدر الطاقة."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل بنية المنخفضات شبه الاستوائية الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم بنية المنخفضات شبه الاستوائية على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ناقش المعايير التي تساعد على التمييز بين منخفض شبه استوائي ومنخفض خارج مداري."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر بنية المنخفضات شبه الاستوائية أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6530,55,'["شرح آليات بنية المنخفضات شبه الاستوائية","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('atmospheric-river-cyclone-interaction','تفاعل الأنهار الجوية مع المنخفضات','نقل الرطوبة والجبهات والهطول الغزير','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تتصل ممرات نقل بخار الماء بمنخفضات عميقة وجبهات نشطة، فتزيد إمداد الرطوبة إلى مناطق الرفع. يعتمد الهطول الفعلي على الاستقرار والتضاريس وسرعة انتقال النظام وكفاءة الهطول."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل تفاعل الأنهار الجوية مع المنخفضات الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم تفاعل الأنهار الجوية مع المنخفضات على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل خريطة نقل بخار الماء المتكامل مع خريطة الجبهات لتحديد مناطق الهطول المحتمل."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر تفاعل الأنهار الجوية مع المنخفضات أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6540,55,'["شرح آليات تفاعل الأنهار الجوية مع المنخفضات","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص'),
('synoptic-diagnostic-case-study','دراسة تشخيصية سينوبتيكية متكاملة','دمج خرائط السطح والطبقات العليا والسبر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتطلب التشخيص السينوبتيكي المتكامل دمج الضغط السطحي والارتفاعات والحرارة والدوامية والرطوبة والرياح الرأسية والسبر. يبدأ التحليل بتحديد البنية واسعة النطاق ثم يفسر آليات الطقس المحلي وحدود التنبؤ."},{"type":"heading","text":"الحقول اللازمة للتشخيص"},{"type":"text","text":"يتطلب تحليل دراسة تشخيصية سينوبتيكية متكاملة الجمع بين حقول الضغط والارتفاع والحرارة والرياح والدوامية والرطوبة والحركة الرأسية، مع اختيار المستويات المناسبة للظاهرة. يجب توحيد أوقات التحليل والتحقق من مصدر البيانات ودقة الشبكة قبل مقارنة الخرائط."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["ابدأ بتحديد النمط واسع النطاق وموقعه وحركته.","افحص التدرجات الحرارية والقص الرأسي وعلاقة الرياح بالضغط.","حدد مناطق التقارب والتباعد والرفع أو الهبوط المحتمل.","قارن التشخيص بالسبر والرصد السطحي ومنتجات الأقمار.","صغ سيناريو تطور مع بدائل واضحة ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل خرائط متتابعة","text":"اختر ثلاث فترات تحليل متعاقبة وطبق مفاهيم دراسة تشخيصية سينوبتيكية متكاملة على الحقول نفسها. تتبع انتقال البنية وتغير شدتها، ثم قارن التفسير مع الطقس المرصود دون افتراض أن كل إشارة ديناميكية تنتج أثراً سطحياً مباشراً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اكتب تقرير حالة من صفحة واحدة يربط خريطة السطح و500 هكتوباسكال والسبر الرأسي بالرصد الفعلي."},{"type":"heading","text":"مزالق التشخيص"},{"type":"list","items":["الاعتماد على خريطة مستوى واحد فقط.","إهمال تطور النظام زمنياً.","الخلط بين الارتباط الديناميكي والسبب المباشر.","عدم مراعاة اختلاف الإحداثيات والاصطلاحات.","إغفال عدم اليقين ومحدودية البيانات."]},{"type":"callout","text":"قاعدة تحليلية: لا تعتمد تشخيصاً سينوبتيكياً نهائياً قبل اختبار اتساقه مع أكثر من حقل رأسي ومصدر رصدي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر دراسة تشخيصية سينوبتيكية متكاملة أداة لفهم تطور الأنظمة الجوية واسعة النطاق وربط الديناميكا بالطقس، ويؤكد أهمية التحليل متعدد المستويات والمتابعة الزمنية."}]}'::jsonb,6550,55,'["شرح آليات دراسة تشخيصية سينوبتيكية متكاملة","اختيار الحقول والمستويات الملائمة للتحليل","إعداد تشخيص جوي مدعوم بالرصد"]'::jsonb,'الأنظمة الجوية الإقليمية والتشخيص')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='الديناميكا الجبهية والموجية' then u1.id else u2.id end,
'الديناميكا الجوية المتقدمة والتحليل السينوبتيكي',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;